parameters.functionCode:
// Determine follow-up strategy based on attempt number
const followupCount = items[0].json.fields['Followup Count'] || 0;
const firstName = items[0].json.fields['Contact Person'].split(' ')[0] || 'there';
const companyName = items[0].json.fields['Company Name'];
const painPoint = items[0].json.fields['Pain Point'];
const location = items[0].json.fields['Location'];

let subject = '';
let body = '';
let followupType = '';

if (followupCount === 0) {
  // First follow-up: Gentle reminder
  followupType = 'gentle_reminder';
  subject = `${firstName} - following up`;
  body = `Hi ${firstName},\n\nI know you're busy, so I'll keep this brief.\n\nI reached out last week about helping ${companyName} with ${painPoint}. I totally understand if the timing isn't right or if it's not a fit.\n\nIf you're interested, I'd still love to have that conversation. If not, just let me know and I won't bother you again.\n\nEither way, I hope ${companyName} continues to thrive in ${location}.\n\nBest,\nOtto`;
} else if (followupCount === 1) {
  // Second follow-up: Value-add
  followupType = 'value_add';
  subject = `${firstName} - thought you'd find this useful`;
  body = `Hi ${firstName},\n\nI wanted to follow up, but rather than just asking again, I thought I'd share something that might be immediately useful for ${companyName}:\n\n[Industry-specific tip or resource]\n\nThis has been working really well for other businesses in ${location}.\n\nStill happy to chat if you'd like to explore how we could help ${companyName} specifically, but either way, hope this is helpful.\n\nBest,\nOtto\n\nP.S. If you're not interested in hearing from me, just reply with "not interested" and I'll remove you from my list immediately.`;
} else {
  // Final follow-up: Break-up email
  followupType = 'breakup';
  subject = `${firstName} - should I close your file?`;
  body = `Hi ${firstName},\n\nI've reached out a couple of times about helping ${companyName} with ${painPoint}, but I haven't heard back.\n\nThat's totally fine - I know things get busy and this might not be a priority right now.\n\nI'm going to assume it's not a fit and won't reach out again unless you tell me otherwise.\n\nIf I'm wrong and you're still interested, just reply to this email and we can set up that call.\n\nEither way, I wish you and ${companyName} all the best in ${location}.\n\nCheers,\nOtto`;
}

return [{
  json: {
    ...items[0].json,
    email: items[0].json.fields['Email'],
    subject: subject,
    body: body,
    followupType: followupType,
    followupCount: followupCount + 1
  }
}];

